(()=>{'use strict';const $=id=>document.getElementById(id);let records=[];const say=t=>$('company-console-status').textContent=t;async function api(method='GET',body){const r=await fetch('/api/designer/business-book',{method,headers:{'content-type':'application/json'},...(body?{body:JSON.stringify(body)}:{})}),d=await r.json();if(!r.ok)throw Error(d.error);return d;}const el=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e;};async function refresh(){try{records=(await api()).records;render();}catch(e){say(e.message);}}
function render(){for(const [kind,target]of [['company','company-records'],['platform','account-records']]){const host=$(target);host.replaceChildren();const shown=records.filter(r=>r.kind===kind);if(!shown.length)host.append(el('p',kind==='company'?'Add your first company or brand above.':'Save your platform profile links. Authorization is still required for live publishing and metrics.'));for(const r of shown){const p=r.payload,card=el('article');card.className='record';card.append(el('h3',p.name),el('p',p.location),el('p',p.description),el('p',kind==='company'?'Stage: '+p.stage:'Saved profile link · Authorization required'),el('p','Next action: '+(p.next||'Set your next action')));if(p.website){const link=el('a','Open website or profile');link.href=p.website;link.target='_blank';link.rel='noopener';card.append(link);}const edit=el('button','Edit');edit.onclick=()=>{const f=$(kind==='company'?'company-profile-form':'platform-account-form');f.dataset.id=r.id;Object.entries(p).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v;});f.scrollIntoView({behavior:'smooth'});};card.append(edit);if(kind==='company'){const prepare=el('button','Use this company in website builder');prepare.onclick=()=>{if(!confirm('Load this company into your website draft? Your products stay in the current catalogue.'))return;const key='zuxuru-fashion-service-v1',s=JSON.parse(localStorage.getItem(key)||'{}');s.designer={...s.designer,name:p.name,location:p.location,story:p.description,email:p.contact.includes('@')?p.contact:'',url:p.website};localStorage.setItem(key,JSON.stringify(s));document.dispatchEvent(new Event('fashion-storefront-updated'));const f=$('designer-form');Object.entries(s.designer).forEach(([k,v])=>{if(f.elements[k])f.elements[k].value=v;});location.hash='storefront-editor';say('Company loaded into the website draft. Wait for Cloud saved, then edit and preview.');};card.append(prepare);}const remove=el('button','Remove');remove.onclick=async()=>{if(!confirm('Remove '+p.name+' from your dashboard? This does not close the company or remove its external profiles.'))return;try{await api('DELETE',{id:r.id});refresh();}catch(e){say(e.message);}};card.append(remove);host.append(card);}}$('company-count').textContent=records.filter(r=>r.kind==='company').length;}
for(const [id,kind]of [['company-profile-form','company'],['platform-account-form','platform']])$(id).onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{await api('POST',{kind,id:f.dataset.id,payload:Object.fromEntries(new FormData(f))});f.reset();delete f.dataset.id;await refresh();say('Saved to your private account.');}catch(e){say(e.message);}finally{b.disabled=false;}};$('company-refresh').onclick=refresh;refresh();})();
